-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.demonhunter.devourer.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.demonhunter.devourer.Description"] = "Recomendada para Devorador. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza Raio do Caos. Junto a isso, lembretes do que o assistente deixa por sua conta: Metamorfose do Caos, A Caçada e Lâmina-caótica sempre que estiverem prontos em combate, Interromper em um lançamento interrompível, e Borrão sempre que estiver pronto em combate. Lançamentos inimigos ficam ocultos em combate, então Interromper só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Borrão é com você."
L["rm.retail.demonhunter.devourer.guide.Name"] = "Referência (Icy Veins)"
L["rm.retail.demonhunter.devourer.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Aniquilador da Icy Veins. A maioria dos seus bônus fica oculta em combate no Midnight, então ela não pode funcionar lá; a Fúria fica oculta no Retail, então Raio do Caos espera apenas pelo próprio custo. Fora de Metamorfose do Caos: Consumir com Estouro Anímico, Ceifar, Imolação de Alma quando não estiver queimando, Lâmina-caótica e A Caçada assim que Metamorfose do Caos estiver pronta, Metamorfose do Caos, Talho Voraz, Raio do Caos, Consumir. Dentro dela: Devorar com Estouro Anímico, Raio do Caos, os golpes de Marcado pelo Caos se você os tiver, Estrela em Colapso, Abater, Devorar, Imolação de Alma. O Rotation Master não consegue contar Fragmentos de Alma, então Ceifar e Abater são usados assim que saem do tempo de recarga. Lembretes: Interromper e Borrão."
L["rm.retail.demonhunter.devourer.simc.Name"] = "Referência (SimulationCraft)"
L["rm.retail.demonhunter.devourer.simc.Description"] = "Apenas referência, desativada por padrão: a lista de Aniquilador do SimulationCraft, que entra em Metamorfose do Caos assim que ela fica pronta. Os dados de combate ocultos a impedem de funcionar em combate no Midnight. Fora dela: Lâmina-caótica com Mordida do Devorador contra até três inimigos e com Metamorfose do Caos totalmente carregada, Metamorfose do Caos, Consumir com Estouro Anímico, Ceifar, Raio do Caos, Imolação de Alma em grupos de inimigos, Consumir. Dentro dela: Devorar com Estouro Anímico contra um alvo, A Caçada e Lâmina-caótica com Mordida do Devorador, Raio do Caos em grupos de inimigos, Estrela em Colapso, Abater, Raio do Caos, Imolação de Alma, Devorar. Lembretes: Interromper e Borrão."
L["rm.retail.demonhunter.havoc.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.demonhunter.havoc.Description"] = "Recomendada para Devastação. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o assistente do jogo deixa por sua conta: Metamorfose e A Caçada em combate, Retirada Vingativa se você tiver Inércia ou Exergia, Interromper em um lançamento interrompível, e Borrão sempre que estiver pronto em combate. Lançamentos inimigos ficam ocultos em combate, então Interromper só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Borrão é com você. Movimentação, Trevas e berloques ficam com você."
L["rm.retail.demonhunter.havoc.guide.Name"] = "Referência (Icy Veins, SimulationCraft e Wowhead)"
L["rm.retail.demonhunter.havoc.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Devastação dos guias. Suas ativações, Metamorfose e Quebrar Essência ficam ocultas para addons em combate no Midnight, então esta lista não pode funcionar lá; leia-a ou duplique-a para experimentar. A Fúria fica oculta no Retail, então Lâmina Vil não espera ter espaço. Aniquilador Aldrachi: Glaive do Aniquilador quando nem Golpe Rasgante nem Rajada de Glaives estiverem ativos, Golpe do Caos com Golpe Rasgante. Marcado por Vileza: Quebrar Essência, Dança de Lâminas e Golpe do Caos durante Metamorfose. Depois, Dança de Lâminas e Golpe do Caos dentro de Quebrar Essência, Aura de Imolação com duas cargas, Raio Ocular, Lâmina Vil para Inércia, Quebrar Essência quando Raio Ocular estiver a mais de 4 segundos de ficar pronto, Dança de Lâminas, Aura de Imolação contra dois inimigos, Golpe do Caos, Lâmina Vil, Aura de Imolação, Arremessar Glaive, Impulso Vil. Lembretes: Metamorfose depois de gastar Raio Ocular e Dança de Lâminas, A Caçada, Retirada Vingativa, além de Interromper e Borrão."
L["rm.retail.demonhunter.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.demonhunter.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Caçador de Demônios). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Caçador de Demônios compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.demonhunter.vengeance.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.demonhunter.vengeance.Description"] = "Recomendada para Vingança. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o assistente deixa por sua conta: Espinhos Demoníacos, Marca Ardente, Devastação Vil e Metamorfose sempre que estiverem prontos em combate, Interromper em um lançamento interrompível, e Borrão sempre que estiver pronto em combate. Lançamentos inimigos ficam ocultos em combate, então Interromper só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Borrão é com você. Golpe Infernal, Trevas, provocações e berloques ficam com você."
L["rm.retail.demonhunter.vengeance.guide.Name"] = "Referência (Wowhead e Icy Veins)"
L["rm.retail.demonhunter.vengeance.guide.Description"] = "Apenas referência, desativada por padrão: a ordem de Vingança da Wowhead com os objetivos de talentos heroicos da Icy Veins. Seus bônus ficam ocultos em combate no Midnight, então ela não pode funcionar lá; a Fúria fica oculta no Retail, então os gastadores esperam apenas pelo próprio custo e os geradores não evitam estourar o limite. Aniquilador Aldrachi: Glaive do Aniquilador, Fratura com Golpe Rasgante, Cutilada da Alma com Rajada de Glaives. Depois, Fratura com cargas cheias, Bomba Espiritual contra três ou mais inimigos, Aura de Imolação, Signo da Chama, Cutilada da Alma contra um alvo, Devastação Vil, Cutilada da Alma, Fratura, Lâmina Vil, Arremessar Glaive. O Rotation Master não consegue contar Fragmentos de Alma, então Bomba Espiritual segue o número de inimigos. Lembretes: Espinhos Demoníacos quando não estiver ativo, Metamorfose, Marca Ardente, Signo da Malevolência, Entalhador de Alma (Golpe Infernal com duas cargas fica desativado), além de Interromper e Borrão."
L["rm.retail.demonhunter.vengeance.simc.Name"] = "Referência (SimulationCraft)"
L["rm.retail.demonhunter.vengeance.simc.Description"] = "Apenas referência, desativada por padrão: as listas de Vingança do SimulationCraft. Os dados de combate ocultos a impedem de funcionar em combate no Midnight, e a Fúria fica oculta no Retail, então os limites de Fúria ficam de fora. Aniquilador Aldrachi: Signo da Chama e Aura de Imolação primeiro, Metamorfose, o ciclo de Glaive do Aniquilador com Lâmina Vil, Marca Ardente, Signo da Malevolência, Bomba Espiritual em grupos de inimigos, Entalhador de Alma durante Óbito Ígneo, depois Fratura, Cutilada da Alma, Lâmina Vil, Devastação Vil. Aniquilador: gaste uma Queda do Caos pronta com Bomba Espiritual ou Cutilada da Alma, Fratura com dois acúmulos de Queda do Caos, Metamorfose, Bomba Espiritual, Signo da Malevolência, Fratura com cargas cheias, Aura de Imolação, Signo da Chama, Fratura, Cutilada da Alma, Lâmina Vil, Arremessar Glaive. Lembretes: Espinhos Demoníacos, Interromper, Borrão."
